addRepairKB({id:'honeywell-hclass-media',brand:'Honeywell (Datamax/Intermec)',models:['H-4212X','H-4310X','H-4606X','H-4212','H-4310','H-4408','H-4606'],category:'感應器／校正',title:'H-Class / H-Class X｜Paper Out、定位不準、Media Sensor 校正',severity:'舊機高價值',sources:['datamax_hclass'],summary:'H-Class 舊機遇到 Paper Out、換紙後定位錯誤或一直走紙，先做耗材安裝、Media Type、Sensor 清潔與校正，再進 Sensor/線束。不要一開始就換主板。',keyFacts:['舊機先排耗材路徑、Sensor 積塵、標籤背膠與可移動 Sensor 位置。','Gap/Notch 與 Black Mark 必須使用對應偵測方式；特殊預印刷紙容易誤判。','校正成功但實際列印仍漂移時，要再區分 Printer 本機定位與 Driver/格式造成的 Offset。'],engineering:['先做單機 FEED/測試標籤，避免把 BarTender 或 Driver 問題當硬體。','Sensor 讀值幾乎不變時再進接頭、線束、Sensor 供電/訊號；未知 Pin 值不硬套。','老機走紙偏時，Platen、導紙與壓力也會造成看似 Sensor 的定位問題。'],verify:['FEED 一次一張','連印 50 張無累積偏移','冷開機後仍能辨識紙張','換卷後可重新校正'],flow:[['確認耗材與模式','確認 Gap/Mark/Continuous、熱感/熱轉印與紙張安裝。',['正確','設定/安裝錯誤，已修正'],'先排最常見的人為與設定。'],['清潔與定位 Sensor','清紙屑、背膠、碳粉，確認紙縫/黑標真正經過感應區。',['完成','清潔/重定位後正常'],'舊機積塵常見。'],['執行 Media Calibration','依 H-Class 操作/維修手冊做標準校正。',['成功','失敗'],'記錄失敗階段。'],['做單機 FEED / Test Label','不經電腦確認定位。',['單機正常','單機也偏/報錯'],'單機正常先回頭查 Driver/Label Format。'],['觀察 Sensor 反應','有診斷讀值或測試模式時比較 Label/Gap/Mark 反應。',['變化正常','固定/差異很小'],'固定值才提高硬體嫌疑。'],['硬體收斂','斷電查 Sensor、接頭、線束；必要時正常件交叉。',['Sensor/線束方向高','主板輸入方向高','已修復'],'主板最後。']]});

addRepairKB({id:'honeywell-hclass-drive-quality',brand:'Honeywell (Datamax/Intermec)',models:['H-4212X','H-4310X','H-4606X','H-4212','H-4310','H-4408','H-4606'],category:'驅動／列印品質',title:'H-Class / H-Class X｜FEED 不走、異音、列印淡、固定白線',severity:'維修',sources:['datamax_hclass'],summary:'H-Class FEED 不走要先分「控制有反應但機構不動」與「整機/面板無反應」。品質問題則先建立測試基準，再查 Printhead、Platen、壓力與 Drive。',keyFacts:['固定同位置白線清潔後仍存在，提高 Printhead element 嫌疑。','有馬達聲但不走紙時，Gear/Platen/耗材阻力優先於 Main PCB。','完全無馬達動作要再查 Motor、線束、供電與驅動。'],engineering:['空機與裝紙分開測，可快速判斷是不是耗材負載拖住 Drive。','帶電量測只依 Service Manual；不要把其他 Datamax 型號電壓直接套用。'],verify:['FEED 連續 20 次正常','無異音/打齒','測試圖無固定缺線','連續列印溫升正常'],flow:[['按 FEED 判斷反應','觀察面板、馬達聲與 Platen。',['有聲但不走','完全沒動作','可走但異音'],'先分流。'],['空機測試','移除紙/碳帶後短測 Drive。',['空機正常','空機仍異常'],'空機正常多為耗材阻力/路徑。'],['檢查 Platen / Gear / Belt','看卡滯、磨損、鬆脫、殘膠。',['發現異常','外觀正常'],'先機構後電子。'],['建立列印測試圖','固定耗材、速度、濃度。',['固定白線','整體太淡','單側淡','品質正常'],'把品質問題分類。'],['清潔 Printhead / Platen','IPA 清潔並檢查滾輪表面。',['改善','無改善'],'清潔後重印同圖。'],['深入 Drive / Printhead','斷電查 Motor/Printhead 線束；交叉正常件。',['Motor/Drive 方向高','Printhead 方向高','主板方向高'],'主板結論要有隔離證據。']]});

addRepairKB({id:'honeywell-mclass-core',brand:'Honeywell (Datamax/Intermec)',models:['M-4206','M-4210','M-4308'],category:'感應器／機構',title:'M-Class Mark II｜Paper Out、一直走紙、FEED 不走、列印品質',severity:'舊機高價值',sources:['datamax_mclass'],summary:'M-Class Mark II 舊機排查重點是先切開耗材/校正、Drive 機構、Printhead/Platen 與電腦端，不要直接用更換主板解決所有症狀。',keyFacts:['Paper Out/跳標優先做耗材安裝、Sensor 清潔與 Calibration。','FEED 有馬達聲但紙不走，優先查 Platen/Gear/耗材阻力。','固定缺線先清 Printhead，再用測試圖確認固定 dot failure。'],engineering:['老機需特別注意 Platen 硬化、軸承阻力、齒輪磨耗與接頭氧化。','更換零件後一定做冷機/熱機與連續列印驗證。'],verify:['FEED 一次一張','50 張無跳標','無異音','條碼品質穩定'],flow:[['單機 FEED / Test','先不接電腦。',['正常','Paper Out/跳標','不走紙'],'把軟體問題切開。'],['Paper Out/跳標分流','確認紙種、Sensor 位置、清潔並校正。',['恢復','仍異常','不適用'],'仍異常再查 Sensor。'],['不走紙分流','聽 Motor、有無 Platen 動作。',['有聲不走','完全沒聲','不適用'],'有聲多先看機構。'],['清潔 Printhead / Platen','建立同一測試圖比較。',['品質正常','固定白線','單側淡/太淡'],'固定白線提高頭嫌疑。'],['檢查機構與線束','Gear、Platen、Motor、Printhead cable。',['找到異常','外觀正常'],'斷電執行。'],['電子層收斂','必要時查 PSU Rail、Motor Driver、Head drive。',['PSU/Driver 方向高','Main PCB 方向高','已修復'],'依 Service Manual 量測。']]});

addRepairKB({id:'honeywell-px240s-baseline',brand:'Honeywell (Datamax/Intermec)',models:['PX240S'],category:'通用維修',title:'PX240S｜快速基線：紙張偵測、列印品質、連線、Cutter',severity:'基礎覆蓋',sources:['honeywell_pm45'],summary:'PX240S 若暫時缺少機型專屬 Service Manual，可先用工業型 Honeywell 的通用排查順序縮小問題；特定 Pin、電壓與拆機步驟仍必須回查 PX240S 文件。',keyFacts:['先用本機 Test/Config 分離 Printer 與 Driver/Host。','Media/Sensor 問題先做安裝、Sensor 位置/清潔、校正。','Cutter 完全不動與會動但卡住要分開。'],engineering:['此條目是基線流程，不把其他 Honeywell 型號的數值直接套到 PX240S。'],verify:['本機 Test 正常','實際工作連續列印正常','重開機後設定保留'],flow:[['確認故障類型','先分紙張/碳帶、品質、連線、切刀、電源。',['紙張/碳帶','品質','連線','切刀','電源'],'先不要混在一起查。'],['做本機 Test/Config','不經電腦。',['正常','本機也異常'],'正常先查 Host/Driver。'],['耗材/Sensor 基線','安裝、Media Type、Sensor 清潔/位置、Calibration。',['恢復','仍異常','不適用'],'不適用就跳過。'],['品質基線','清 Printhead/Platen，固定速度與濃度。',['恢復','固定缺線','單側淡','不適用'],'固定缺線才提高 Printhead。'],['連線/Cutter 分流','LAN 走 Link→IP→Ping→Port；Cutter 走 Mode→清潔→Home/Motor。',['恢復','仍異常','不適用'],'先分軟硬體。'],['深入前查 Service Manual','進 Sensor pin、PSU、主板、拆裝前確認 PX240S 專屬資料。',['已取得資料','需暫停深入'],'避免跨型號誤判。']]});

addRepairKB({id:'godex-zx400i-cal',brand:'GoDEX',models:['ZX420i+','ZX430i+'],category:'感應器／校正',title:'ZX420i+/ZX430i+｜紙張校正、跳標、Paper Out、黑標',severity:'高頻',sources:['godex_zx400i'],summary:'ZX400i+ 系列原廠產品頁直接提供紙張校正資源。換紙、一直送紙、抓不到 Gap/Black Mark 時，先做 Sensor/紙張類型與校正，再查硬體。',keyFacts:['機器有獨立紙張偵測/校正操作。','Gap/Black Mark/Continuous 要與實際耗材一致。','校正仍失敗才進 Sensor/線束。'],engineering:['預印刷、透明底紙、特殊缺口紙要特別注意感應位置。','有 Printer 自測/Config 時先做單機測試。'],verify:['FEED 一次一張','連印 50 張無跳標','換卷後可重新校正'],flow:[['確認紙張安裝與類型','Gap/Mark/Continuous 正確。',['正確','已修正'],'先排設定。'],['清潔並確認 Sensor 位置','清紙屑/背膠，對準 Gap/Mark。',['完成','清潔後正常'],'再校正。'],['執行紙張校正','依原廠 ZX400i+ 校正程序。',['成功','失敗'],'不要連續亂按。'],['單機 FEED / Test','確認不經電腦定位。',['正常','仍跳標/Paper Out'],'正常轉查 Driver/格式。'],['耗材交叉','換已知正常紙卷。',['正常','仍異常'],'排除耗材干擾。'],['硬體收斂','斷電查 Sensor/線束/接頭。',['Sensor/線束方向高','主板方向高','已修復'],'主板最後。']]});

addRepairKB({id:'godex-ez-industrial',brand:'GoDEX',models:['EZ2250i','EZ2350i','EZ6250i','EZ6350i'],category:'校正／列印品質',title:'EZ2250i/EZ2350i/EZ6250i/EZ6350i｜紙張校正、Ribbon、品質、Drive',severity:'高價值',sources:['godex_ez2250','godex_family'],summary:'GoDEX EZ 工業系列遇到換紙後定位不準、Ribbon/品質或走紙異常，先用原廠紙張校正與標準測試切開 Sensor、機構與電腦端。',keyFacts:['EZ2250i/EZ2350i 原廠頁有紙張校正資源。','品質問題先固定紙、Ribbon、速度與濃度，再看 Printhead/Platen。','走紙不動先分 Motor 有聲/無聲。'],engineering:['工業舊機的 Ribbon path、Platen、Gear 與壓力狀況常與品質綁在一起。'],verify:['FEED 正常','Ribbon 不皺/不斷','測試圖均勻','連印 100 張穩定'],flow:[['紙張校正','確認耗材類型後做原廠 Calibration。',['成功','仍失敗'],'失敗才深入 Sensor。'],['測試列印','固定同一測試圖。',['品質正常','整體淡','固定白線','皺碳/單側淡'],'分類品質。'],['清潔 Head/Platen','清潔並看滾輪磨耗。',['改善','無改善','Platen 異常'],'Platen 是常見接觸基準。'],['Ribbon 路徑/壓力','確認碳帶裝法、張力、左右壓力與走紙。',['已修復','仍異常'],'皺碳不要只加熱。'],['Drive 分流','FEED 不走時分有馬達聲/完全無聲。',['有聲不走','完全無聲','不適用'],'有聲先機構。'],['深入硬體','Sensor/Motor/Printhead 線束與主板隔離。',['找到故障','主板方向高'],'依對應型號手冊。']]});

addRepairKB({id:'godex-rt700-series',brand:'GoDEX',models:['RT700i+','RT730i+','RT863i+'],category:'桌上型／校正／連線',title:'RT700i+/RT730i+/RT863i+｜一直走紙、定位、USB/LAN、列印品質',severity:'常見',sources:['godex_rt700'],summary:'RT700 系列原廠資料包含紙張校正。桌上機排查先用 FEED/Calibration 切開 Sensor，再用 USB/LAN 交叉切開電腦端。',keyFacts:['換紙後一直送紙或定位跑掉先重新校正。','本機 FEED/Test 正常但電腦不印，優先 Driver/Port/Queue。','固定白線清潔後仍在再查 Printhead。'],engineering:['USB 完全無辨識與有辨識但送印失敗是兩條路。'],verify:['FEED 一張','Windows 正常列印','網路機型 Ping/Port 正常','品質穩定'],flow:[['紙張校正','依 RT700 系列紙張校正流程。',['成功','失敗'],'先做最小動作。'],['本機 Test','印 Config/Test。',['正常','本機異常'],'正常先查電腦。'],['USB/LAN 分流','USB 看裝置管理員；LAN 看 Link/IP/Ping/Port。',['恢復','仍異常','不適用'],'不要一開始拆主板。'],['清潔 Printhead/Platen','固定測試圖。',['品質正常','固定白線','太淡/單側淡'],'分類。'],['Sensor/走紙硬體','校正仍失敗查 Sensor、導紙、Platen。',['找到異常','仍異常'],'先機構。'],['電子層','必要時再查介面板/主板。',['介面/主板方向高','已修復'],'要有交叉測試。']]});

addRepairKB({id:'godex-desktop-baseline',brand:'GoDEX',models:['GE300','GE330','EZ120','G500+','G530+','G500','G530','EZ520','EZ530','DT2x'],category:'桌上型／通用維修',title:'GoDEX 桌上型｜校正、紙不走、列印空白、USB/LAN 快速排查',severity:'基礎覆蓋',sources:['godex_g500','godex_family'],summary:'GoDEX 桌上型共通排查：先做 FEED/紙張校正，再分列印品質與電腦連線。舊 G/EZ 系列特別注意 Sensor、Platen、齒輪與電源供應器老化。',keyFacts:['紙會走但全白：先分 Direct Thermal / Thermal Transfer、耗材面向與 Printhead。','紙完全不走：先聽 Motor，再查卡紙/Platen/Gear。','USB/LAN 本機 Test 正常時先查 Driver/Port。'],engineering:['不同機型 Sensor 位置與按鍵校正方式不同，深入操作依該型號 User Manual。'],verify:['FEED 正常','本機 Test 正常','電腦送印正常','冷熱機均穩定'],flow:[['FEED/Calibration','看是否能一次一張。',['正常','一直走紙','完全不走'],'先分 Sensor/Drive。'],['耗材與模式','紙種、Ribbon、熱感/熱轉印。',['正確','已修正'],'空白列印常見。'],['清潔 Sensor/Head/Platen','做基礎保養。',['改善','無改善'],'再深入。'],['本機 Test','不經電腦。',['正常','異常'],'正常查 Driver/Port。'],['Drive / Sensor 分流','一直走紙查 Sensor；不走紙查 Motor/Gear/Platen。',['找到方向','仍不明'],'不要混查。'],['硬體交叉','線材、Sensor、Motor、PSU、主板依手冊逐層。',['已修復','主板方向高'],'主板最後。']]});

addRepairKB({id:'tsc-tx610-small-label',brand:'TSC',models:['TX610'],category:'高解析度／校正／品質',title:'TX610 600 dpi｜小標籤定位、細字條碼、校正、固定缺線',severity:'高價值',sources:['tsc_tx'],summary:'TX610 是 600 dpi 桌上型，原廠特別強調精準 calibration/registration。小標籤、細字與高密度條碼問題要先把 Sensor/定位處理好，再調速度、濃度與 Printhead。',keyFacts:['600 dpi 對小標籤定位與耗材一致性更敏感。','不要用高 Darkness 補償錯誤壓力或不匹配 Ribbon。','固定同位置缺線仍要用 Test Pattern 排 Printhead dot。'],engineering:['先降低速度建立基準，避免高解析度下熱量與機械誤差一起混入。','BarTender Offset/Driver 也可能造成看似 Printer drift。'],verify:['小標籤連續 100 張定位穩定','細條碼可讀','無固定缺線','重開機仍穩定'],flow:[['確認紙張 Sensor/類型','Gap/Mark 與 Sensor 位置。',['正確','已修正'],'小標籤特別敏感。'],['執行 Calibration','用機器/工具做紙張校正。',['成功','仍失敗'],'失敗換已知正常耗材。'],['降低速度建立基準','同一圖檔低速測。',['改善','無改善'],'改善表示熱/機械餘裕不足。'],['清潔 Head/Platen','看固定缺線與接觸。',['正常','固定白線','單側淡'],'分類。'],['切開 Printer 與 Driver','印內建 Test 與 BarTender 各一份。',['內建正常','內建也異常'],'內建正常查軟體。'],['硬體收斂','Printhead/Platen/Sensor/線束依結果交叉。',['已修復','Printhead 方向高','Sensor/主板方向高'],'有證據再換件。']]});

addRepairKB({id:'tsc-da210-da220',brand:'TSC',models:['DA210','DA220'],category:'熱感／校正／Cutter',title:'DA210/DA220｜只走紙不印、抓不到 Gap/Black Mark、Cutter、USB/LAN',severity:'高頻',sources:['tsc_da'],summary:'DA210/DA220 為 Direct Thermal 桌上型，紙會走但全白時先確認使用熱感紙與紙面方向；定位則先查 Gap/Black Mark/Notch Sensor 與 Calibration。',keyFacts:['DA 系列是 Direct Thermal only，不使用 Ribbon。','標準支援 gap、black mark、notch sensing。','DA220 比 DA210 有更多連線選項；LAN 問題仍走 Link→IP→Ping→Port。'],engineering:['用指甲/摩擦測試熱感面只能當快速初判，最終用已知正常熱感紙交叉。','Cutter 有 full/partial cut 選項時先確認 Mode/設定。'],verify:['熱感測試圖正常','FEED 一張','Cutter 連切 30 次','USB/LAN 實際送印正常'],flow:[['確認紙材','必須是可用 Direct Thermal 的熱感紙且熱感面朝 Printhead。',['正確','紙材/方向錯誤，已修正'],'DA 系列不靠 Ribbon。'],['紙張校正','確認 Gap/Black Mark/Notch 後做 Calibration。',['成功','失敗'],'一直走紙先查這裡。'],['清潔 Head / Sensor / Platen','去除紙屑與殘膠。',['恢復','仍異常'],'熱感紙粉常見。'],['本機 Test','不經電腦。',['正常','本機也不印'],'本機正常轉 Driver/Port。'],['Cutter / 連線分流','Cutter 查 Mode/卡紙/Home；LAN 查 Link/IP/Ping/Port。',['恢復','仍異常','不適用'],'分開處理。'],['硬體收斂','固定白線查 Printhead；不走紙查 Motor/Gear；Sensor 固定查線束。',['已修復','需換件'],'依手冊。']]});
